-- TP-04: historial de cambios de precio de un servicio (regla 10) y margen mínimo de alerta. Solo agrega.

CREATE TABLE IF NOT EXISTS "historial_precios_proceso" (
  "id_historial" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_proceso" INTEGER NOT NULL REFERENCES "procesos" ("id_proceso") ON DELETE CASCADE,
  "campo" VARCHAR(80) NOT NULL,                 -- p. ej. «Precio plan 20», «Costo directo»
  "valor_anterior" VARCHAR(60),
  "valor_nuevo" VARCHAR(60),
  "usuario" VARCHAR(150) NOT NULL,
  "fecha" TIMESTAMP NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "ix_historial_precios_proceso" ON "historial_precios_proceso" ("id_proceso", "fecha");

INSERT INTO "parametros_tienda" ("clave", "valor", "tipo", "descripcion") VALUES
  ('margenMinimoPorcentaje', '30', 'DECIMAL', 'Margen bruto mínimo (%) bajo el cual el administrador ve una alerta en rojo')
ON CONFLICT ("clave") DO NOTHING;
